I run the gates in order before launch, and any failure halts the round. First, I confirm that spe/predictions/r04.yaml and spe/plans/r04.md are in HEAD and have not changed since. I run `git diff --quiet HEAD -- spe/predictions/r04.yaml spe/plans/r04.md` to check. From the dry run on, I treat r04.yaml as frozen. Second, `python3 spe/evals/graders/grade.py --selftest` must pass the oracle answers and fail the empty and wrong answers. In the same gate I check that spe/evals/tasks/answers.json holds exactly the 50 ticket ids in `args.tickets`. Third, I regrade round 3's saved results (spe/evals/results/r03.json) with this round's grade.py and compare them to round 3's recorded scores. This is the control. A change there is a grader change. I log it in spe/failures.md before going further. Fourth, I launch a dry run with `{round: 4, trials: 1, only: [{config: 'B', ticket: 't001'}, {config: 'C2', ticket: 't001'}, {config: 'C2', ticket: 't017'}]}`. Every trial must match the schema with an empty leak scan, one grader row, and one tone score. I put the measured cost per trial in place of `estTrialUsd`. Then I commit spe/evals/harness/r04-workflow.js locally as "spe(r04): evaluate harness", with no push. Last, I launch the full run with `spendCapUsd: 40`.

Defaults I chose: the script assumes three things. A runner at `bin/triage-run` takes a ticket as JSON on stdin and prints `label`, `reply`, `metrics`, and `tool_log`. grade.py accepts `--answers`, `--results`, and `--json`. The launcher passes ticket text in `args.tickets` with labels removed, so trial agents never need to open `spe/`.

```js
export const meta = {
  name: 'triage-spe-evaluate',
  description: 'SPE evaluate step for the triage agent. Runs each config on every ticket, grades labels with grade.py, judges reply tone with an Opus judge, tops up mixed cells, then runs a failure analysis and a completeness critic.',
  phases: ['Preflight', 'Trials', 'Grade', 'Top-up', 'Judge', 'Synthesis'],
}

// Saved as spe/evals/harness/r04-workflow.js. The round comes only from args.round.

// ---------- Arguments ----------
const A = args ?? {}
const ROUND = Number(A.round)
if (!Number.isInteger(ROUND) || ROUND < 1) throw new Error('args.round is required')
const ROUND_ID = 'r' + String(ROUND).padStart(2, '0')

const CONFIGS = A.configs ?? ['B', 'C2']
const TICKETS = A.tickets ?? []
const TRIALS = A.trials ?? 5
const EXPECTED_TICKETS = A.expectedTickets ?? 50
const ONLY = Array.isArray(A.only) && A.only.length > 0 ? A.only : null
const DRY = ONLY !== null
const RUNNER = A.runner ?? 'bin/triage-run'
const MAX_RETRIES = A.maxRetries ?? 1
const CAP_USD = A.spendCapUsd ?? 40
const EST_TRIAL_USD = A.estTrialUsd ?? 0.05
const OPERATOR_USD = A.operatorUsd ?? 0.01
const EST_JUDGE_USD = A.estJudgeUsd ?? 0.15
const TOPUP_PER_CELL = A.topUpPerCell ?? 3
const TOPUP_TOTAL = A.topUpTotal ?? 60
const MAX_LEAK_VOIDS = A.maxLeakVoids ?? 2
const GRADE_CHUNK = A.gradeChunk ?? 100
const TRANSCRIPT_DIR = A.transcriptDir ?? null
const JUDGE_MODEL = 'opus'
const CATEGORIES = ['billing', 'bug', 'how-to', 'account', 'outage']
const PRIORITIES = ['P1', 'P2', 'P3', 'P4']
const KEY_MARKERS = ['spe/', 'answers.json', 'grade.py', 'judge.md']
const JUDGE_NOTE = 'The tone judge is Opus. The triage configs run on Sonnet, so judge and agent share a model family. No cross-family judge is available in this harness, so tone scores may share Claude blind spots.'

// ---------- Validation ----------
const ticketById = new Map(TICKETS.map(t => [t.id, t]))
if (ticketById.size !== TICKETS.length) throw new Error('args.tickets has duplicate ids')
if (!DRY && TICKETS.length !== EXPECTED_TICKETS) {
  throw new Error(`args.tickets has ${TICKETS.length} tickets but the plan says ${EXPECTED_TICKETS}`)
}
for (const t of TICKETS) {
  if (!t.id || !t.body) throw new Error(`ticket ${t.id ?? '?'} is missing id or body`)
  if ('category' in t || 'priority' in t || 'label' in t || 'reference' in t) {
    throw new Error(`ticket ${t.id} carries a reference label. Strip labels before passing tickets to trials.`)
  }
}
const cells = DRY
  ? ONLY.map(o => ({ config: o.config, ticket: o.ticket }))
  : CONFIGS.flatMap(config => TICKETS.map(t => ({ config, ticket: t.id })))
for (const c of cells) {
  if (!CONFIGS.includes(c.config)) throw new Error(`unknown config ${c.config}`)
  if (!ticketById.has(c.ticket)) throw new Error(`unknown ticket ${c.ticket}`)
}

// ---------- Helpers ----------
const mean = xs => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null)
const r3 = x => (x == null ? null : Math.round(x * 1000) / 1000)
const isDone = t => t.status === 'completed' && !t.voided
const isScored = t => isDone(t) && typeof t.pass === 'boolean'

function chunk(xs, n) {
  const out = []
  for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n))
  return out
}

function hash(s) {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

function shuffled(arr, seed) {
  const a = arr.slice()
  let x = hash(seed) || 1
  for (let i = a.length - 1; i > 0; i--) {
    x ^= x << 13
    x ^= x >>> 17
    x ^= x << 5
    x >>>= 0
    const j = x % (i + 1)
    const tmp = a[i]
    a[i] = a[j]
    a[j] = tmp
  }
  return a
}

// ---------- Budget ----------
const budget = { spent: 0, reserved: 0, halted: false, skipped: [] }

function tryReserve(usd, what) {
  if (budget.halted || budget.spent + budget.reserved + usd > CAP_USD) {
    if (!budget.halted) log(`Spend cap $${CAP_USD} would be crossed. Skipping ${what} and everything after it.`)
    budget.halted = true
    budget.skipped.push(what)
    return false
  }
  budget.reserved += usd
  return true
}

function settle(reservedUsd, actualUsd) {
  budget.reserved -= reservedUsd
  budget.spent += actualUsd
}

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['status', 'commands_run'],
  properties: {
    status: { type: 'string', enum: ['completed', 'harness_error', 'rate_limited'] },
    error: { type: 'string' },
    commands_run: { type: 'array', items: { type: 'string' } },
    output: {
      type: 'object',
      properties: {
        label: {
          type: 'object',
          properties: { category: { type: 'string' }, priority: { type: 'string' } },
        },
        reply: { type: 'string' },
      },
    },
    metrics: {
      type: 'object',
      properties: {
        runtime_ms: { type: 'number' },
        tool_calls: { type: 'number' },
        tool_errors: { type: 'number' },
        tokens_in: { type: 'number' },
        tokens_out: { type: 'number' },
        cost_usd: { type: 'number' },
      },
    },
    tool_log: {
      type: 'array',
      items: { type: 'object', properties: { name: { type: 'string' }, args: { type: 'string' } } },
    },
  },
}

const GRADE_SCHEMA = {
  type: 'object',
  required: ['grader_ok', 'rows'],
  properties: {
    grader_ok: { type: 'boolean' },
    error: { type: 'string' },
    rows: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'category_ok', 'priority_ok'],
        properties: {
          trial_id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
        },
      },
    },
  },
}

const SCAN_SCHEMA = {
  type: 'object',
  required: ['leaked', 'not_found', 'scanned'],
  properties: {
    scanned: { type: 'number' },
    leaked: {
      type: 'array',
      items: { type: 'object', properties: { trial_id: { type: 'string' }, evidence: { type: 'string' } } },
    },
    not_found: { type: 'array', items: { type: 'string' } },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['key', 'tone'],
        properties: { key: { type: 'string' }, tone: { type: 'number' }, reason: { type: 'string' } },
      },
    },
  },
}

const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['prediction_checks', 'failures', 'proposals', 'all_within_band'],
  properties: {
    prediction_checks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          metric: { type: 'string' },
          config: { type: 'string' },
          predicted: { type: 'number' },
          band: { type: 'number' },
          measured: { type: ['number', 'null'] },
          within_band: { type: ['boolean', 'null'] },
          scorable: { type: 'boolean' },
        },
      },
    },
    failures: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          title: { type: 'string' },
          kind: { type: 'string', enum: ['model', 'harness', 'voided', 'saturation', 'grader'] },
          evidence: { type: 'string' },
          trial_ids: { type: 'array', items: { type: 'string' } },
        },
      },
    },
    proposals: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          change: { type: 'string' },
          reason: { type: 'string' },
          failure_ids: { type: 'array', items: { type: 'string' } },
        },
      },
    },
    all_within_band: { type: 'boolean' },
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps', 'verdict'],
  properties: {
    complete: { type: 'boolean' },
    gaps: {
      type: 'array',
      items: { type: 'object', properties: { check: { type: 'string' }, detail: { type: 'string' } } },
    },
    verdict: { type: 'string' },
  },
}

// ---------- Prompts ----------
function trialPrompt(config, ticket, trialId) {
  return `You operate one trial of the triage agent eval. Trial id: ${trialId}.

Your job is to run one command and report what it prints. You are not the triage agent. Do not triage the ticket yourself.

Rules:
- Run exactly one shell command, shown below. Do not open, list, search, or read any file. Do not look inside spe/ or any other folder.
- Do not change the ticket text. Do not fix, reword, or fill in the runner's output.

Command. Pipe the ticket JSON into the runner with a quoted heredoc:
${RUNNER} --config ${config} --trial-id ${trialId} --json <<'TICKET_EOF'
${JSON.stringify(ticket)}
TICKET_EOF

The runner prints one JSON object with the fields label, reply, metrics, and tool_log. Copy label and reply into output. Copy metrics and tool_log as printed. Set status to completed.
If the runner exits non-zero or prints no valid JSON, set status to harness_error and put the last 300 characters of stderr in error.
If the error mentions a rate limit, 429, 529, or overloaded, set status to rate_limited.
List every shell command you ran, verbatim, in commands_run.`
}

function gradePrompt(payload) {
  return `You run the code grader for the triage eval. You do not grade anything yourself.

You may read spe/evals/graders/grade.py and spe/evals/tasks/answers.json. Do not edit any file in the repository.

1. Write the JSON array below to a new file created with mktemp.
2. Run: python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --results <that file> --json
3. The grader prints one row per trial with trial_id, category_ok, and priority_ok. Return those rows exactly as printed and set grader_ok to true.
If the grader exits non-zero, prints invalid JSON, or returns a different number of rows than you sent, set grader_ok to false. Return the rows you have and put the stderr tail in error.

Trial labels (${payload.length} rows):
${JSON.stringify(payload)}`
}

function scanPrompt(ids) {
  return `You audit trial transcripts for answer-key access. Do not open any file under spe/ yourself.

Transcripts are under ${TRANSCRIPT_DIR}. Each trial agent was labeled "trial <id>". Find the transcript for each trial id listed below.
Report a trial as leaked if any of its tool calls reads, lists, searches, or opens a path that contains spe/, answers.json, grade.py, or judge.md. Quote the tool call as evidence.
Put trial ids you could not find in not_found. Report only what you saw. Set scanned to the number of transcripts you checked.

Trial ids:
${ids.join('\n')}`
}

function judgePrompt(ticket, keyed) {
  return `You judge the tone of draft support replies. Read spe/evals/graders/judge.md first and apply its rubric exactly, on its scale.

Score tone only. Do not score whether the category, the priority, or the facts are right. Score each reply on its own against the rubric. Do not rank the replies against each other.
All the replies below answer the same ticket. They come from different runs and appear in random order. Do not edit any file.

Ticket:
${JSON.stringify({ subject: ticket.subject ?? '', body: ticket.body })}

Replies:
${keyed.map(x => `[${x.key}]\n${x.t.output.reply}`).join('\n\n')}

Return one score for every key.`
}

function analysisPrompt(perConfig, mixedCells, failing) {
  return `You write the failure analysis for round ${ROUND_ID} of the triage eval. Do not edit any file. The main session writes your output to disk.

You may read spe/predictions/${ROUND_ID}.yaml, spe/plans/${ROUND_ID}.md, spe/evals/tasks/answers.json, and spe/failures.md.

1. For every metric and config in spe/predictions/${ROUND_ID}.yaml, give the predicted value, the band, the measured value from the results below, and whether the measured value falls inside the band. Use only measured numbers from the results. If a metric has no measured value, set measured and within_band to null.
2. If every config hits the maximum on a metric, mark that prediction scorable false and add a saturation failure that proposes harder tickets.
3. Group the failing trials into failure modes. Give each one an id of the form "${ROUND_ID} F<n>" starting at F1, a short title, a kind, the evidence, and the trial ids. Keep model failures apart from harness errors and voided trials.
4. Propose changes for the next round. Each proposed config changes one thing. Tie each proposal to a failure id.
Set all_within_band to true only if every scorable prediction is inside its band.

Results by config. Accuracy and tone use main trials only. Top-up trials are reported separately:
${JSON.stringify(perConfig, null, 2)}

Cells with mixed results after top-up:
${JSON.stringify(mixedCells)}

Failing trials (up to 30 per config):
${JSON.stringify(failing)}`
}

function criticPrompt(report) {
  return `You are the completeness critic for round ${ROUND_ID} of the triage eval. Do not edit any file. You may read spe/predictions/${ROUND_ID}.yaml and spe/plans/${ROUND_ID}.md.

Check the run report below against the plan and list every gap. Check at least these:
- Every config and ticket cell has ${TRIALS} completed main trials, or each missing trial has a logged reason (harness error, rate limit, budget skip, or void).
- Every completed trial has a grader row, and every completed main trial with a reply has a tone score.
- Every metric in the predictions file has a measured value for every config.
- Accuracy counts only completed trials. Harness errors and rate limits are not counted as model failures.
- Spend stayed under the cap, and every skip is listed.
- The leak scan covered every trial, and voided trials are left out of the metrics.
- The failure analysis gives an id for every failure mode it names, and each proposal changes one thing.
Set complete to true only when you find no gaps.

Run report:
${JSON.stringify(report, null, 2)}`
}

// ---------- Trials ----------
const trials = []
const leakScan = { transcript_voided: [], not_found: [], errors: [], ran: false }
const gradeLog = []

function selfReportLeak(rec) {
  if (rec.commands_run.length === 0) return 'reported no commands, so the run cannot be audited'
  for (const c of rec.commands_run) {
    if (!c.includes(RUNNER)) return `ran a command other than the runner: ${c.slice(0, 120)}`
    if (KEY_MARKERS.some(m => c.includes(m))) return `command touched an answer-key path: ${c.slice(0, 120)}`
  }
  for (const t of rec.tool_log) {
    const s = `${t.name ?? ''} ${t.args ?? ''}`
    if (KEY_MARKERS.some(m => s.includes(m))) return `triage tool call touched an answer-key path: ${s.slice(0, 120)}`
  }
  return null
}

async function runTrial(config, ticket, kind, k, phaseName) {
  const trialId = `${ROUND_ID}-${config}-${ticket.id}-${kind === 'main' ? 'm' : 'u'}${k}`
  const rec = { trialId, config, ticket: ticket.id, kind, status: 'pending', attempts: 0 }
  trials.push(rec)
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    if (!tryReserve(EST_TRIAL_USD, trialId)) {
      rec.status = 'skipped_budget'
      return rec
    }
    rec.attempts += 1
    let r
    try {
      r = await agent(trialPrompt(config, ticket, trialId), {
        label: `trial ${trialId}`,
        phase: phaseName,
        schema: TRIAL_SCHEMA,
      })
    } catch (e) {
      r = { status: 'harness_error', error: String(e).slice(0, 300), commands_run: [] }
    }
    const runnerCost = typeof r?.metrics?.cost_usd === 'number' ? r.metrics.cost_usd : null
    settle(EST_TRIAL_USD, runnerCost === null ? EST_TRIAL_USD : runnerCost + OPERATOR_USD)
    rec.status = r?.status ?? 'harness_error'
    rec.error = r?.error ?? null
    rec.commands_run = r?.commands_run ?? []
    rec.output = r?.output ?? null
    rec.metrics = r?.metrics ?? null
    rec.tool_log = r?.tool_log ?? []
    if (rec.status === 'completed') break
  }
  if (rec.status === 'completed') {
    const reason = selfReportLeak(rec)
    if (reason) {
      rec.voided = true
      rec.void_reason = reason
    }
  }
  return rec
}

async function scanTranscripts(ids, phaseName) {
  if (!TRANSCRIPT_DIR) {
    log('No args.transcriptDir was given. Only the self-reported command scan ran.')
    return
  }
  if (!ids.length) return
  let res
  try {
    res = await agent(scanPrompt(ids), { label: `leak scan ${phaseName}`, phase: phaseName, schema: SCAN_SCHEMA })
  } catch (e) {
    leakScan.errors.push(String(e).slice(0, 200))
    return
  }
  leakScan.ran = true
  leakScan.not_found.push(...(res.not_found ?? []))
  for (const l of res.leaked ?? []) {
    const t = trials.find(x => x.trialId === l.trial_id)
    if (t && !t.voided) {
      t.voided = true
      t.void_reason = `transcript scan: ${String(l.evidence).slice(0, 160)}`
      leakScan.transcript_voided.push(l.trial_id)
    }
  }
}

const voidCount = () => trials.filter(t => t.voided).length

// ---------- Grading ----------
async function gradeBatch(batch, label, phaseName) {
  const payload = batch.map(t => ({
    trial_id: t.trialId,
    ticket_id: t.ticket,
    label: { category: t.output?.label?.category ?? '', priority: t.output?.label?.priority ?? '' },
  }))
  let res
  try {
    res = await agent(gradePrompt(payload), { label, phase: phaseName, schema: GRADE_SCHEMA })
  } catch (e) {
    return { ok: false, error: String(e).slice(0, 300) }
  }
  if (!res?.grader_ok) return { ok: false, error: res?.error ?? 'grader reported failure' }
  const byId = new Map(res.rows.map(r => [r.trial_id, r]))
  if (byId.size !== payload.length || payload.some(p => !byId.has(p.trial_id))) {
    return { ok: false, error: `grader returned ${byId.size} rows for ${payload.length} trials` }
  }
  for (const t of batch) {
    const row = byId.get(t.trialId)
    t.category_ok = row.category_ok
    t.priority_ok = row.priority_ok
    t.pass = row.category_ok && row.priority_ok
  }
  return { ok: true }
}

async function gradeAll(list, tag, phaseName) {
  if (!list.length) return null
  const parts = chunk(list, GRADE_CHUNK)
  const results = await parallel(
    parts.map((part, i) => () => gradeBatch(part, `grade ${tag} ${i + 1}/${parts.length}`, phaseName)),
  )
  const errors = results.filter(r => !r || !r.ok).map(r => r?.error ?? 'no result')
  gradeLog.push({ tag, trials: list.length, batches: parts.length, errors })
  return errors.length ? errors.join(' | ') : null
}

// ---------- Judge ----------
async function judgeTicket(tid) {
  const ticket = ticketById.get(tid)
  const items = trials.filter(t => t.ticket === tid && t.kind === 'main' && isDone(t) && t.output?.reply)
  if (!items.length) return
  if (!tryReserve(EST_JUDGE_USD, `judge ${tid}`)) return
  const keyed = shuffled(items, `${ROUND_ID}:${tid}`).map((t, i) => ({ key: `R${i + 1}`, t }))
  let res = null
  try {
    res = await agent(judgePrompt(ticket, keyed), {
      label: `judge ${tid}`,
      phase: 'Judge',
      schema: JUDGE_SCHEMA,
      model: JUDGE_MODEL,
    })
  } catch (e) {
    log(`Judge failed on ${tid}: ${String(e).slice(0, 200)}`)
  }
  settle(EST_JUDGE_USD, EST_JUDGE_USD)
  const byKey = new Map((res?.scores ?? []).map(s => [s.key, s]))
  for (const x of keyed) {
    const s = byKey.get(x.key)
    if (s && typeof s.tone === 'number') {
      x.t.tone = s.tone
      x.t.tone_reason = s.reason ?? ''
    }
  }
  const missing = keyed.filter(x => typeof x.t.tone !== 'number').length
  if (missing) log(`Judge left ${missing} replies unscored on ${tid}.`)
}

// ---------- Reporting ----------
function cellReport() {
  return cells.map(c => {
    const ts = trials.filter(t => t.config === c.config && t.ticket === c.ticket)
    const main = ts.filter(t => t.kind === 'main')
    const scored = main.filter(isScored)
    const top = ts.filter(t => t.kind === 'topup' && isScored(t))
    return {
      config: c.config,
      ticket: c.ticket,
      main_scored: scored.length,
      main_passes: scored.filter(t => t.pass).length,
      topup_scored: top.length,
      topup_passes: top.filter(t => t.pass).length,
      missing: main.filter(t => !isScored(t)).map(t => `${t.trialId}:${t.voided ? 'voided' : t.status}`),
    }
  })
}

// Accuracy and tone use main trials only. Top-up trials go only to mixed cells, so they are reported apart.
function summarize(config) {
  const all = trials.filter(t => t.config === config)
  const main = all.filter(t => t.kind === 'main' && isScored(t))
  const top = all.filter(t => t.kind === 'topup' && isScored(t))
  const rate = (xs, f) => r3(mean(xs.map(t => (f(t) ? 1 : 0))))
  const metric = k => r3(mean(main.map(t => t.metrics?.[k]).filter(v => typeof v === 'number')))
  const myCells = cellReport().filter(c => c.config === config && c.main_scored > 0)
  return {
    main_trials_scored: main.length,
    category_acc: rate(main, t => t.category_ok),
    priority_acc: rate(main, t => t.priority_ok),
    both_acc: rate(main, t => t.pass),
    invalid_label_rate: rate(
      main,
      t => !CATEGORIES.includes(t.output?.label?.category) || !PRIORITIES.includes(t.output?.label?.priority),
    ),
    cells_all_pass: r3(mean(myCells.map(c => (c.main_passes === c.main_scored ? 1 : 0)))),
    tone_mean: r3(mean(main.map(t => t.tone).filter(v => typeof v === 'number'))),
    runtime_ms_mean: metric('runtime_ms'),
    tool_calls_mean: metric('tool_calls'),
    tool_errors_mean: metric('tool_errors'),
    tokens_in_mean: metric('tokens_in'),
    tokens_out_mean: metric('tokens_out'),
    cost_usd_mean: metric('cost_usd'),
    topup_trials_scored: top.length,
    topup_pass_rate: rate(top, t => t.pass),
    voided: all.filter(t => t.voided).length,
    harness_errors: all.filter(t => t.status === 'harness_error').length,
    rate_limited: all.filter(t => t.status === 'rate_limited').length,
    skipped_budget: all.filter(t => t.status === 'skipped_budget').length,
  }
}

function coverage() {
  const done = trials.filter(isDone)
  const judgeable = done.filter(t => t.kind === 'main' && t.output?.reply)
  return {
    planned_main: cells.length * TRIALS,
    main_completed: done.filter(t => t.kind === 'main').length,
    gradable: done.length,
    graded: done.filter(t => typeof t.pass === 'boolean').length,
    tone_expected: judgeable.length,
    tone_scored: judgeable.filter(t => typeof t.tone === 'number').length,
    grade_log: gradeLog,
  }
}

function budgetReport() {
  return {
    cap_usd: CAP_USD,
    spent_usd: r3(budget.spent),
    spend_basis: 'runner-reported triage cost plus estimated operator and judge cost',
    halted: budget.halted,
    skipped: budget.skipped,
  }
}

function exportTrial(t) {
  return {
    trial_id: t.trialId,
    config: t.config,
    ticket: t.ticket,
    kind: t.kind,
    status: t.status,
    attempts: t.attempts,
    voided: Boolean(t.voided),
    void_reason: t.void_reason ?? null,
    label: t.output?.label ?? null,
    reply: t.output?.reply ?? null,
    category_ok: t.category_ok ?? null,
    priority_ok: t.priority_ok ?? null,
    pass: t.pass ?? null,
    tone: t.tone ?? null,
    tone_reason: t.tone_reason ?? null,
    metrics: t.metrics ?? null,
    error: t.error ?? null,
  }
}

function finish(haltReason, extra = {}) {
  if (haltReason) log(`HALT: ${haltReason}`)
  return {
    round: ROUND,
    round_id: ROUND_ID,
    dry_run: DRY,
    halted: Boolean(haltReason),
    halt_reason: haltReason ?? null,
    judge_note: JUDGE_NOTE,
    budget: budgetReport(),
    leak_scan: { self_voided: voidCount() - leakScan.transcript_voided.length, ...leakScan },
    coverage: coverage(),
    per_config: Object.fromEntries(CONFIGS.map(c => [c, summarize(c)])),
    cells: cellReport(),
    trials: trials.map(exportTrial),
    ...extra,
  }
}

// ---------- Run ----------
async function main() {
  phase('Preflight')
  const runTickets = [...new Set(cells.map(c => c.ticket))]
  const estMain = cells.length * TRIALS * EST_TRIAL_USD
  const estJudge = runTickets.length * EST_JUDGE_USD
  const estTop = DRY ? 0 : TOPUP_TOTAL * EST_TRIAL_USD
  log(`${ROUND_ID}${DRY ? ' dry run' : ''}: ${cells.length} cells x ${TRIALS} trials, configs ${CONFIGS.join(', ')}.`)
  log(`Estimated spend, not measured: trials $${estMain.toFixed(2)}, judge $${estJudge.toFixed(2)}, top-up up to $${estTop.toFixed(2)}. Cap $${CAP_USD}.`)
  if (estMain + estJudge > CAP_USD) {
    log('Warning: the estimate for main trials and judging exceeds the cap. Trials past the cap will be skipped and the run will halt.')
  }

  phase('Trials')
  const mainThunks = []
  for (const c of cells) {
    for (let k = 1; k <= TRIALS; k++) {
      mainThunks.push(() => runTrial(c.config, ticketById.get(c.ticket), 'main', k, 'Trials'))
    }
  }
  await parallel(mainThunks)
  const n = s => trials.filter(t => t.status === s).length
  log(`Main trials: ${n('completed')} completed, ${n('harness_error')} harness errors, ${n('rate_limited')} rate limited, ${n('skipped_budget')} skipped for budget, ${voidCount()} voided by the command scan.`)

  phase('Grade')
  await scanTranscripts(trials.filter(t => t.kind === 'main' && isDone(t)).map(t => t.trialId), 'Grade')
  if (voidCount() > MAX_LEAK_VOIDS) {
    return finish(`${voidCount()} trials touched answer-key paths or ran other commands. The key may be reachable from trial worktrees.`)
  }
  const gErr = await gradeAll(trials.filter(t => t.kind === 'main' && isDone(t)), 'main', 'Grade')
  if (gErr) return finish(`grader broken: ${gErr}`)
  if (budget.halted) return finish('spend cap reached during main trials')

  if (!DRY) {
    phase('Top-up')
    const mixed = cellReport().filter(c => c.main_passes > 0 && c.main_passes < c.main_scored)
    let left = TOPUP_TOTAL
    const thunks = []
    const unserved = []
    for (const c of mixed) {
      const k = Math.min(TOPUP_PER_CELL, left)
      if (k <= 0) {
        unserved.push(`${c.config}/${c.ticket}`)
        continue
      }
      left -= k
      for (let i = 1; i <= k; i++) {
        thunks.push(() => runTrial(c.config, ticketById.get(c.ticket), 'topup', i, 'Top-up'))
      }
    }
    log(`${mixed.length} mixed cells. Queued ${thunks.length} top-up trials against a cap of ${TOPUP_TOTAL}.`)
    if (unserved.length) log(`Top-up cap reached. These cells got no top-up: ${unserved.join(', ')}`)
    await parallel(thunks)
    await scanTranscripts(trials.filter(t => t.kind === 'topup' && isDone(t)).map(t => t.trialId), 'Top-up')
    if (voidCount() > MAX_LEAK_VOIDS) {
      return finish(`${voidCount()} trials touched answer-key paths or ran other commands. The key may be reachable from trial worktrees.`)
    }
    const gErr2 = await gradeAll(trials.filter(t => t.kind === 'topup' && isDone(t)), 'top-up', 'Top-up')
    if (gErr2) return finish(`grader broken on top-up trials: ${gErr2}`)
    if (budget.halted) return finish('spend cap reached during top-up')
  }

  phase('Judge')
  log(JUDGE_NOTE)
  await parallel(runTickets.map(tid => () => judgeTicket(tid)))
  if (budget.halted) return finish('spend cap reached during judging')
  if (DRY) return finish(null)

  phase('Synthesis')
  const perConfig = Object.fromEntries(CONFIGS.map(c => [c, summarize(c)]))
  const failing = CONFIGS.flatMap(c =>
    trials
      .filter(t => t.config === c && isScored(t) && !t.pass)
      .slice(0, 30)
      .map(t => ({
        trial_id: t.trialId,
        config: t.config,
        kind: t.kind,
        ticket: t.ticket,
        ticket_subject: ticketById.get(t.ticket)?.subject ?? '',
        ticket_body: (ticketById.get(t.ticket)?.body ?? '').slice(0, 500),
        got: t.output?.label ?? null,
        category_ok: t.category_ok,
        priority_ok: t.priority_ok,
        tone: t.tone ?? null,
      })),
  )
  const mixedAfter = cellReport().filter(c => {
    const scored = c.main_scored + c.topup_scored
    const passes = c.main_passes + c.topup_passes
    return passes > 0 && passes < scored
  })

  let analysis
  try {
    analysis = await agent(analysisPrompt(perConfig, mixedAfter, failing), {
      label: 'failure analysis',
      phase: 'Synthesis',
      schema: ANALYSIS_SCHEMA,
    })
  } catch (e) {
    analysis = { error: String(e).slice(0, 300) }
  }

  const criticInput = {
    per_config: perConfig,
    coverage: coverage(),
    budget: budgetReport(),
    leak_scan: leakScan,
    voided_trials: trials.filter(t => t.voided).map(t => ({ trial_id: t.trialId, reason: t.void_reason })),
    cells_with_missing_trials: cellReport().filter(c => c.missing.length),
    analysis,
  }
  let critic
  try {
    critic = await agent(criticPrompt(criticInput), {
      label: 'completeness critic',
      phase: 'Synthesis',
      schema: CRITIC_SCHEMA,
    })
  } catch (e) {
    critic = { complete: false, gaps: [{ check: 'critic', detail: String(e).slice(0, 300) }], verdict: 'critic failed' }
  }

  return finish(null, { analysis, critic })
}

return await main()
